    if not d.exists():
        continue
    for p in d.rglob('*'):
        if not p.is_file():
            continue
        sz=p.stat().st_size
        if sz<100 or sz>8_000_000:
            continue
        try:
            data=p.read_bytes()
        except Exception:
            continue
        if not any(n in data for n in needles):
            continue
        hits+=1
        print('FILE', p, 'size', sz)
        for n in needles:
            i=data.find(n)
            if i>=0:
                chunk=data[max(0,i-100):i+500]
                print(chunk.decode('utf-8','ignore')[:600])
                print('---')
        if hits>=6:
            break
    if hits>=6:
        break
print('total_hits_printed', hits)
